import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { getOrdersListWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await getOrdersListWorkflow(req.scope)
    .run({
      input: {
        fields: ["id", "status", "items"],
        variables: {
          skip: 0,
          take: 15,
        }
      }
    })

  res.send(result)
}

